import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Main {
    record Product(String name, int priceCents) { }
    public static void main(String[] args) {
        List<Product> products = new ArrayList<>(List.of(
            new Product("Notebook", 250), new Product("Pen", 50), new Product("Pencil", 50)));
        products.sort(Comparator.comparingInt(Product::priceCents).thenComparing(Product::name));
        products.forEach(p -> System.out.println(p.name() + "=" + p.priceCents()));
    }
}
